package solution

import (
	"errors"
	"reflect"
	"testing"
)

func TestRunWeightedStopsOnSuccess(t *testing.T) {
	stopErr := errors.New("retry")
	calls := 0
	used, err := RunWeighted(5, 3, func(weight int) error {
		calls++
		if calls < 3 {
			return stopErr
		}
		return nil
	})
	if err != nil {
		t.Fatalf("RunWeighted returned error: %v", err)
	}
	if want := []int{3, 6, 12}; !reflect.DeepEqual(used, want) {
		t.Fatalf("used = %v, want %v", used, want)
	}
	if calls != 3 {
		t.Fatalf("action called %d times, want 3", calls)
	}
}

func TestRunWeightedExhaustionReturnsFinalError(t *testing.T) {
	errs := []error{errors.New("first"), errors.New("second"), errors.New("final")}
	calls := 0
	used, err := RunWeighted(3, 1, func(weight int) error {
		e := errs[calls]
		calls++
		return e
	})
	if err != errs[2] {
		t.Fatalf("error = %v, want final action error", err)
	}
	if want := []int{1, 2, 4}; !reflect.DeepEqual(used, want) {
		t.Fatalf("used = %v, want %v", used, want)
	}
	if calls != 3 {
		t.Fatalf("action called %d times, want 3", calls)
	}
}

func TestRunWeightedSaturatesAtMaximumInt(t *testing.T) {
	maxInt := int(^uint(0) >> 1)
	start := maxInt/2 + 1
	failure := errors.New("failure")
	used, err := RunWeighted(4, start, func(int) error { return failure })
	if err != failure {
		t.Fatalf("error = %v, want %v", err, failure)
	}
	want := []int{start, maxInt, maxInt, maxInt}
	if !reflect.DeepEqual(used, want) {
		t.Fatalf("used = %v, want %v", used, want)
	}
}

func TestRunWeightedSingleAttempt(t *testing.T) {
	failure := errors.New("only failure")
	used, err := RunWeighted(1, 7, func(weight int) error {
		if weight != 7 {
			t.Fatalf("weight = %d, want 7", weight)
		}
		return failure
	})
	if err != failure {
		t.Fatalf("error = %v, want %v", err, failure)
	}
	if want := []int{7}; !reflect.DeepEqual(used, want) {
		t.Fatalf("used = %v, want %v", used, want)
	}
}

func TestRunWeightedRejectsInvalidInputWithoutCallingAction(t *testing.T) {
	cases := []struct {
		name     string
		attempts int
		weight   int
	}{
		{name: "zero attempts", attempts: 0, weight: 1},
		{name: "negative attempts", attempts: -1, weight: 1},
		{name: "zero weight", attempts: 1, weight: 0},
		{name: "negative weight", attempts: 1, weight: -1},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			calls := 0
			used, err := RunWeighted(tc.attempts, tc.weight, func(int) error {
				calls++
				return nil
			})
			if err == nil {
				t.Fatal("expected non-nil error")
			}
			if used != nil {
				t.Fatalf("used = %#v, want nil", used)
			}
			if calls != 0 {
				t.Fatalf("action called %d times, want 0", calls)
			}
		})
	}

	used, err := RunWeighted(1, 1, nil)
	if err == nil {
		t.Fatal("nil action: expected non-nil error")
	}
	if used != nil {
		t.Fatalf("nil action: used = %#v, want nil", used)
	}
}

func TestRunWeightedDoesNotRecoverActionPanic(t *testing.T) {
	marker := &struct{}{}
	called := false
	returned := false

	func() {
		defer func() {
			recovered := recover()
			if recovered != marker {
				t.Fatalf("recovered panic = %#v, want marker %#v", recovered, marker)
			}
		}()
		RunWeighted(3, 2, func(int) error {
			called = true
			panic(marker)
		})
		returned = true
	}()

	if !called {
		t.Fatal("action was not called")
	}
	if returned {
		t.Fatal("RunWeighted returned after action panic")
	}
}

package solution

import "testing"

func TestReviewLargeAttemptLimitEarlySuccess(t *testing.T) {
	calls := 0
	used, err := RunWeighted(int(^uint(0)>>1), 1, func(weight int) error {
		calls++
		return nil
	})
	if err != nil || calls != 1 || len(used) != 1 || used[0] != 1 {
		t.Fatalf("used=%v calls=%d err=%v", used, calls, err)
	}
}

